public class CharExploderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("two words", "[a, b, c]",
                CharExploder.allChars(java.util.List.of("ab", "c")).toString());
        check("single word", "[j, a, v, a]",
                CharExploder.allChars(java.util.List.of("java")).toString());
        check("order is preserved across words", "[h, i, y, o]",
                CharExploder.allChars(java.util.List.of("hi", "yo")).toString());
        check("empty strings contribute nothing", "[x, z]",
                CharExploder.allChars(java.util.List.of("", "x", "", "z")).toString());
        check("repeated characters kept", "[o, o, o]",
                CharExploder.allChars(java.util.List.of("oo", "o")).toString());
        check("empty input list", "[]",
                CharExploder.allChars(new java.util.ArrayList<String>()).toString());
        check("total character count", 10,
                CharExploder.allChars(java.util.List.of("hello", "world")).size());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

