public class CharExploder {

    public static java.util.List<String> allChars(java.util.List<String> words) {
        return words.stream()
                .flatMap(word -> word.chars().mapToObj(code -> String.valueOf((char) code)))
                .collect(java.util.stream.Collectors.toList());
    }
}
